#!/usr/bin/env python3
from pwn import *
import sys
import os

def read_rom(filename):
    with open(filename, 'rb') as f:
        return f.read()

def analyze_rom(rom_data):
    # Print basic info
    print(f"ROM Size: {len(rom_data)} bytes")
    print("\nFirst 32 bytes (hex):")
    print(hexdump(rom_data[:32]))

    # Look for ASCII strings
    print("\nPossible ASCII strings:")
    strings = []
    current_string = []
    for byte in rom_data:
        if 32 <= byte <= 126:  # Printable ASCII
            current_string.append(chr(byte))
        else:
            if current_string:
                if len(current_string) >= 4:  # Only show strings of 4+ chars
                    strings.append(''.join(current_string))
                current_string = []

    for s in strings:
        print(f"  {s}")

    # Look for potential 4004 instructions
    print("\nInstruction analysis:")
    for i in range(0, len(rom_data), 2):
        if i+1 >= len(rom_data):
            break
        opcode = rom_data[i] >> 4
        operand = rom_data[i] & 0xF
        next_byte = rom_data[i+1]

        if opcode == 0x0:
            print(f"0x{i:04x}: NOP")
        elif opcode == 0x1:
            print(f"0x{i:04x}: JCN {operand:x} {next_byte:02x}")
        elif opcode == 0x4:
            addr = ((operand & 0xF) << 8) | next_byte
            print(f"0x{i:04x}: JUN {addr:03x}")
        elif opcode == 0x5:
            addr = ((operand & 0xF) << 8) | next_byte
            print(f"0x{i:04x}: JMS {addr:03x}")
        elif opcode == 0xD:
            print(f"0x{i:04x}: LDM {operand:x}")

def main():
    if not os.path.exists('chal.rom'):
        print("[!] chal.rom not found! Extracting from challenge.zip...")
        os.system('cd /home/ctfplayer/ctf_files && unzip -o challenge.zip')
        os.system('cp /home/ctfplayer/ctf_files/chal.rom .')

    rom_data = read_rom('chal.rom')
    analyze_rom(rom_data)

if __name__ == '__main__':
    main()

